'use strict';

/**
* Return the index of the last falsy element in a single-precision floating-point strided array.
*
* @module @stdlib/blas-ext-base-slast-index-of-falsy
*
* @example
* import Float32Array from '@stdlib/array-float32';
* import slastIndexOfFalsy from '@stdlib/blas-ext-base-slast-index-of-falsy';
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 0.0, -1.0, 3.0 ] );
*
* var idx = slastIndexOfFalsy( x.length, x, 1 );
* // returns 5
*
* @example
* import Float32Array from '@stdlib/array-float32';
* import slastIndexOfFalsy from '@stdlib/blas-ext-base-slast-index-of-falsy';
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 0.0, -1.0, 3.0 ] );
*
* var idx = slastIndexOfFalsy.ndarray( x.length, x, 1, 0 );
* // returns 5
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var slastIndexOfFalsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	slastIndexOfFalsy = main;
} else {
	slastIndexOfFalsy = tmp;
}


// EXPORTS //

export default slastIndexOfFalsy;

// exports: { "ndarray": "slastIndexOfFalsy.ndarray" }
